const PRECISION: usize = 6;

pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0_f32 {
        return if value.is_sign_negative() {
            String::from("-0")
        } else {
            String::from("0")
        };
    }

    let negative = value.is_sign_negative();
    let magnitude = if negative {
        -(value as f64)
    } else {
        value as f64
    };

    let scientific = format!("{:.*e}", PRECISION - 1, magnitude);
    let (mantissa, exponent_text) = scientific.split_once('e').unwrap();
    let exponent: i32 = exponent_text.parse().unwrap();
    let digits: String = mantissa.chars().filter(|ch| *ch != '.').collect();

    let mut formatted = if exponent < -4 || exponent >= PRECISION as i32 {
        format_scientific(&digits, exponent)
    } else {
        format_fixed(&digits, exponent)
    };

    if negative {
        formatted.insert(0, '-');
    }

    formatted
}

fn format_scientific(digits: &str, exponent: i32) -> String {
    let trimmed_len = digits.trim_end_matches('0').len();
    let mut out = String::new();
    out.push(digits.as_bytes()[0] as char);

    if trimmed_len > 1 {
        out.push('.');
        out.push_str(&digits[1..trimmed_len]);
    }

    out.push('e');
    if exponent >= 0 {
        out.push('+');
    } else {
        out.push('-');
    }
    out.push_str(&format!("{:02}", exponent.abs()));
    out
}

fn format_fixed(digits: &str, exponent: i32) -> String {
    let decimal_index = exponent + 1;
    let mut out = String::new();

    if decimal_index <= 0 {
        out.push('0');
        out.push('.');
        out.push_str(&"0".repeat((-decimal_index) as usize));
        out.push_str(digits);
    } else {
        let decimal_index = decimal_index as usize;
        if decimal_index >= digits.len() {
            out.push_str(digits);
            out.push_str(&"0".repeat(decimal_index - digits.len()));
        } else {
            out.push_str(&digits[..decimal_index]);
            out.push('.');
            out.push_str(&digits[decimal_index..]);
        }
    }

    trim_trailing_fraction_zeros(&mut out);
    out
}

fn trim_trailing_fraction_zeros(text: &mut String) {
    if !text.contains('.') {
